using Confluent.Kafka;using Medzo.CatalogueInventory.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Logging;
namespace Medzo.CatalogueInventory.Infrastructure.Messaging;
public sealed class OutboxPublisher(IServiceScopeFactory scopes,IProducer<string,string> producer,ILogger<OutboxPublisher> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken stoppingToken){using var timer=new PeriodicTimer(TimeSpan.FromSeconds(2));while(await timer.WaitForNextTickAsync(stoppingToken)){using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<CatalogueInventoryDbContext>();var rows=await db.OutboxMessages.Where(x=>x.ProcessedAtUtc==null&&x.Attempts<10).OrderBy(x=>x.OccurredAtUtc).Take(50).ToListAsync(stoppingToken);foreach(var row in rows)try{await producer.ProduceAsync(row.Topic,new Message<string,string>{Key=row.Key,Value=row.Payload},stoppingToken);row.MarkProcessed();}catch(Exception e){row.MarkFailed(e.Message);log.LogError(e,"Publishing outbox message {Id} failed",row.Id);}await db.SaveChangesAsync(stoppingToken);}}}
